-- The built-in Resolve Stage template (`resolveStageTemplate`, spec §2.3.4 "The Resolve Stage"), which the conflict chain's Resolve Stages are linked to, unless the user has a template of the name already.
INSERT INTO "stage_templates" ("id", "stage") VALUES ('resolve', '{"kind":"agent","key":"resolve","name":"Resolve","duty":"implements","brief":"Resolve the conflicts the merge of the base left in the Task''s branch. Edit each conflicted file so it keeps what both sides meant, read with the Task''s Plan and what the base changed, and remove every conflict marker (the <<<<<<<, ======= and >>>>>>> lines). Edit files only and don''t run git: The Office commits the merge as the Stage ends. If you can''t resolve a conflict, end the Stage failed and say why.","session":"fresh","budget":620000,"optional":false,"mergeBaseFirst":true}'::jsonb) ON CONFLICT DO NOTHING;
